world.addEventListener('click',e=>{const item=e.target.closest('.item');if(e.target.classList.contains('diceRoll'))item.querySelector('.diceValue').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][Math.floor(Math.random()*6)];if(e.target.classList.contains('scorePlus')){const n=e.target.parentElement.querySelector('strong');n.textContent=+n.textContent+1;persist()}if(e.target.dataset.work){item.querySelector('.phaseCard').textContent=e.target.dataset.work;item.querySelectorAll('[data-work]').forEach(x=>x.classList.toggle('active',x===e.target));persist()}if(e.target.dataset.wlight){item.querySelectorAll('[data-wlight]').forEach(x=>x.classList.toggle('on',x===e.target));item.querySelector('.phaseCard').textContent=e.target.dataset.wlight==='green'?'Alles gut ✨':e.target.dataset.wlight==='yellow'?'Leiser werden 👀':'Stopp · Aufmerksamkeit'}if(e.target.classList.contains('timerPlus')||e.target.classList.contains('timerMinus')){const out=item.querySelector('.timerValue');out.dataset.left=Math.max(0,+out.dataset.left+(e.target.classList.contains('timerPlus')?60:-60));showTime(out,+out.dataset.left)}if(e.target.classList.contains('timerStart'))runTimer(item,e.target);if(e.target.classList.contains('timerReset')){clearInterval(item._timer);const out=item.querySelector('.timerValue');out.dataset.left=300;showTime(out,300);item.querySelector('.progress i').style.width='100%'}if(e.target.classList.contains('stopwatchStart'))runStopwatch(item,e.target);if(e.target.classList.contains('stopwatchReset')){clearInterval(item._sw);item._sw=null;item._swSec=0;item.querySelector('.stopwatchValue').textContent='00:00'}if(e.target.classList.contains('visualStart'))runVisual(item,e.target);if(e.target.classList.contains('visualReset')){clearInterval(item._visual);item._visual=null;const r=item.querySelector('.ring');r.dataset.left=900;r.querySelector('span').textContent='15:00';r.style.background='conic-gradient(var(--lilac) 100%,#eee 0)'}});
function showTime(out,s){out.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function runTimer(item,btn){if(item._timer){clearInterval(item._timer);item._timer=null;btn.textContent='▶';return}const out=item.querySelector('.timerValue'),start=+out.dataset.left||300;btn.textContent='⏸';item._timer=setInterval(()=>{let s=Math.max(0,+out.dataset.left-1);out.dataset.left=s;showTime(out,s);item.querySelector('.progress i').style.width=(s/start*100)+'%';if(!s){clearInterval(item._timer);item._timer=null;btn.textContent='▶'}},1000)}
function runStopwatch(item,btn){if(item._sw){clearInterval(item._sw);item._sw=null;btn.textContent='▶';return}item._swSec=item._swSec||0;btn.textContent='⏸';item._sw=setInterval(()=>{item._swSec++;showTime(item.querySelector('.stopwatchValue'),item._swSec)},1000)}
function runVisual(item,btn){if(item._visual){clearInterval(item._visual);item._visual=null;btn.textContent='▶';return}const r=item.querySelector('.ring');btn.textContent='⏸';item._visual=setInterval(()=>{let s=Math.max(0,+r.dataset.left-1);r.dataset.left=s;showTime(r.querySelector('span'),s);r.style.background='conic-gradient(var(--lilac) '+(s/900*100)+'%,#eee 0)';if(!s){clearInterval(item._visual);item._visual=null;btn.textContent='▶'}},1000)}
