function fmtBoardDate(v){try{return new Date(v).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'})}catch(e){return''}}
async function renderBoardLibrary(){const list=$('#boardLibraryList'),rows=(await dbAll()).sort((x,y)=>String(y.updatedAt).localeCompare(String(x.updatedAt)));list.innerHTML=rows.map(r=>'<article class="boardCard '+(r.id===currentBoardId?'current':'')+'" data-board-id="'+esc(r.id)+'"><div class="boardPreview">'+(r.preview?'<img src="'+r.preview+'" alt="">':'<div class="boardPreviewEmpty">Board</div>')+'</div><div class="boardCardBody"><div class="boardCardTop"><div><b>'+esc(r.name||'Mein Board')+'</b><small>Zuletzt '+esc(fmtBoardDate(r.updatedAt))+'</small></div>'+(r.id===currentBoardId?'<span class="currentBadge">Geöffnet</span>':'')+'</div><div class="boardCardActions"><button data-board-open="'+esc(r.id)+'">Öffnen</button><button data-board-duplicate="'+esc(r.id)+'">Duplizieren</button><button data-board-rename="'+esc(r.id)+'">Umbenennen</button><button class="danger" data-board-delete="'+esc(r.id)+'">Löschen</button></div></div></article>').join('')||'<div class="materialEmpty">Noch keine Boards.</div>';$('[data-board-open]').forEach(b=>b.onclick=()=>openBoardById(b.dataset.boardOpen));$('[data-board-duplicate]').forEach(b=>b.onclick=()=>duplicateBoardById(b.dataset.boardDuplicate));$('[data-board-rename]').forEach(b=>b.onclick=()=>renameBoardById(b.dataset.boardRename));$('[data-board-delete]').forEach(b=>b.onclick=()=>deleteBoardById(b.dataset.boardDelete))}
async function showBoardLibrary(){await persistNow();await renderBoardLibrary();$('#boardLibraryModal').classList.remove('hidden')}
function hideBoardLibrary(){$('#boardLibraryModal').classList.add('hidden')}
async function openBoardById(id){if(id===currentBoardId){hideBoardLibrary();return}await persistNow();const rec=await dbGet(id);if(!rec)return;currentBoardId=id;localStorage.setItem(CURRENT_BOARD_KEY,id);history=[];future=[];applyBoardData(rec.data);hideBoardLibrary();toast('Board geöffnet')}
async function createNewBoard(){await persistNow();const name=(prompt('Name des neuen Boards','Neues Board')||'').trim();if(!name)return;const now=new Date().toISOString(),data={id:'board-'+Date.now()+Math.random().toString(36).slice(2,6),name,createdAt:now,updatedAt:now,bg:'',items:[],strokes:[]};await dbPut({id:data.id,name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});currentBoardId=data.id;localStorage.setItem(CURRENT_BOARD_KEY,currentBoardId);history=[];future=[];applyBoardData(data);hideBoardLibrary();toast('Neues Board erstellt')}
async function duplicateBoardById(id){const rec=await dbGet(id);if(!rec)return;const now=new Date().toISOString(),data=structuredClone(rec.data);data.id='board-'+Date.now()+Math.random().toString(36).slice(2,6);data.name=(rec.name||'Board')+' – Kopie';data.createdAt=now;data.updatedAt=now;await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:rec.preview||boardPreview(data),data});await renderBoardLibrary();toast('Board dupliziert')}
async function renameBoardById(id){const rec=await dbGet(id);if(!rec)return;const name=(prompt('Board umbenennen',rec.name||'Mein Board')||'').trim();if(!name)return;rec.name=name;rec.updatedAt=new Date().toISOString();rec.data.name=name;rec.data.updatedAt=rec.updatedAt;await dbPut(rec);if(id===currentBoardId){board.name=name;board.updatedAt=rec.updatedAt;setBoardTitle()}await renderBoardLibrary();toast('Board umbenannt')}
async function deleteBoardById(id){const rec=await dbGet(id);if(!rec||!confirm('Board „'+(rec.name||'Mein Board')+'“ wirklich löschen?'))return;await dbRemove(id);let rows=await dbAll();if(id===currentBoardId){if(!rows.length){const now=new Date().toISOString(),data={id:'board-'+Date.now(),name:'Mein Board',createdAt:now,updatedAt:now,bg:'',items:[],strokes:[]};await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});rows=[await dbGet(data.id)]}const next=rows.sort((x,y)=>String(y.updatedAt).localeCompare(String(x.updatedAt)))[0];currentBoardId=next.id;localStorage.setItem(CURRENT_BOARD_KEY,currentBoardId);history=[];future=[];applyBoardData(next.data)}await renderBoardLibrary();toast('Board gelöscht')}
async function importBoardFile(file){try{const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.items)||!Array.isArray(data.strokes))throw Error('Ungültiges Board');const now=new Date().toISOString();data.id='board-'+Date.now()+Math.random().toString(36).slice(2,6);data.name=data.name||file.name.replace(/\.json$/i,'')||'Importiertes Board';data.createdAt=now;data.updatedAt=now;await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});await renderBoardLibrary();toast('Board importiert')}catch(e){console.error(e);toast('Import fehlgeschlagen')}}
$('#boardsBtn').onclick=showBoardLibrary;$('#boardLibraryClose').onclick=hideBoardLibrary;$('#boardNewBtn').onclick=createNewBoard;$('#boardImportBtn').onclick=()=>$('#boardImportInput').click();$('#boardImportInput').onchange=e=>{const f=e.target.files?.[0];if(f)importBoardFile(f);e.target.value=''};$('#boardLibraryModal').onclick=e=>{if(e.target.id==='boardLibraryModal')hideBoardLibrary()};
$('#saveBtn').onclick=async()=>{await persistNow();toast('Board gespeichert')};$('#exportBtn').onclick=()=>{const a=document.createElement('a'),blob=new Blob([JSON.stringify(serialize(),null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download=((board.name||'Kathleen-Board').replace(/[^a-z0-9äöüß_-]+/gi,'_'))+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};$('#backBtn').onclick=()=>location.href='../../#tools';
async function rpc(n,b){const r=await fetch(SB+n,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json'},body:JSON.stringify(b||{})});const raw=await r.text(),x=raw?(()=>{try{return JSON.parse(raw)}catch(e){return raw}})():null;if(!r.ok){const msg=(x&&typeof x==='object'&&(x.message||x.hint||x.details))||raw||('Supabase '+r.status);const err=new Error(msg);err.status=r.status;err.code=x?.code||'';throw err}return x}
const TEACHER_WINDOW_KEY='kathleenTeacherControlWindowV181';
let teacherDrag=null;
function loadTeacherWindowLayout(){try{return JSON.parse(localStorage.getItem(TEACHER_WINDOW_KEY)||'null')||{mode:'float',minimized:false,x:null,y:null}}catch(e){return{mode:'float',minimized:false,x:null,y:null}}}
function saveTeacherWindowLayout(v){localStorage.setItem(TEACHER_WINDOW_KEY,JSON.stringify(v))}
function clampTeacherWindow(panel,x,y){const r=panel.getBoundingClientRect(),pad=8,maxX=Math.max(pad,innerWidth-r.width-pad),maxY=Math.max(68,innerHeight-r.height-pad);return{x:Math.min(Math.max(pad,x),maxX),y:Math.min(Math.max(68,y),maxY)}}
function applyTeacherWindowLayout(){const p=$('#studentsPanel');if(!p)return;const st=loadTeacherWindowLayout();p.classList.remove('dockLeft','dockRight','floating','minimized');p.style.left='';p.style.right='';p.style.top='';p.style.bottom='';p.style.transform='';if(st.minimized)p.classList.add('minimized');if(st.mode==='left')p.classList.add('dockLeft');else if(st.mode==='right')p.classList.add('dockRight');else{p.classList.add('floating');requestAnimationFrame(()=>{const pr=p.getBoundingClientRect();const x=Number.isFinite(st.x)?st.x:Math.max(80,innerWidth-pr.width-24),y=Number.isFinite(st.y)?st.y:86;const pos=clampTeacherWindow(p,x,y);p.style.left=pos.x+'px';p.style.top=pos.y+'px'})}updateTeacherWindowButtons()}
function updateTeacherWindowButtons(){const p=$('#studentsPanel');if(!p)return;const st=loadTeacherWindowLayout();$('#teacherDockLeft')?.classList.toggle('active',st.mode==='left');$('#teacherFloat')?.classList.toggle('active',st.mode==='float');$('#teacherDockRight')?.classList.toggle('active',st.mode==='right');if($('#teacherMinimize'))$('#teacherMinimize').textContent=st.minimized?'□':'—'}
function setTeacherWindowMode(mode){const st=loadTeacherWindowLayout();st.mode=mode;st.minimized=false;saveTeacherWindowLayout(st);applyTeacherWindowLayout()}
function toggleTeacherMinimize(){const p=$('#studentsPanel'),st=loadTeacherWindowLayout();st.minimized=!st.minimized;if(st.mode==='float'&&!st.minimized){const r=p.getBoundingClientRect();st.x=r.left;st.y=r.top}saveTeacherWindowLayout(st);applyTeacherWindowLayout()}
function setupTeacherWindow(){const p=$('#studentsPanel'),head=$('#teacherControlDragHandle');if(!p||!head)return;applyTeacherWindowLayout();$('#teacherDockLeft').onclick=e=>{e.stopPropagation();setTeacherWindowMode('left')};$('#teacherFloat').onclick=e=>{e.stopPropagation();setTeacherWindowMode('float')};$('#teacherDockRight').onclick=e=>{e.stopPropagation();setTeacherWindowMode('right')};$('#teacherMinimize').onclick=e=>{e.stopPropagation();toggleTeacherMinimize()};$('#teacherClosePanel').onclick=e=>{e.stopPropagation();p.classList.add('hidden')};head.addEventListener('dblclick',e=>{if(!e.target.closest('button'))toggleTeacherMinimize()});head.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button'))return;const st=loadTeacherWindowLayout();if(st.mode!=='float'||st.minimized)return;const r=p.getBoundingClientRect();teacherDrag={dx:e.clientX-r.left,dy:e.clientY-r.top};head.setPointerCapture?.(e.pointerId);p.classList.add('dragging')});head.addEventListener('pointermove',e=>{if(!teacherDrag)return;const pos=clampTeacherWindow(p,e.clientX-teacherDrag.dx,e.clientY-teacherDrag.dy);p.style.left=pos.x+'px';p.style.top=pos.y+'px'});const end=e=>{if(!teacherDrag)return;teacherDrag=null;p.classList.remove('dragging');const r=p.getBoundingClientRect(),st=loadTeacherWindowLayout();st.mode='float';st.x=r.left;st.y=r.top;saveTeacherWindowLayout(st);head.releasePointerCapture?.(e.pointerId)};head.addEventListener('pointerup',end);head.addEventListener('pointercancel',end);window.addEventListener('resize',()=>{if(!p.classList.contains('hidden'))applyTeacherWindowLayout()})}
function classroomUrls(){if(!classroom?.room_code)return null;const base=new URL('.',location.href);return{student:new URL('student.html?room='+classroom.room_code,base).href,present:new URL('present.html?room='+classroom.room_code,base).href}}
function phaseLabel(v){return({free:'Freie Phase',explain:'Erklärung',solo:'Einzelarbeit',group:'Gruppenarbeit',class:'Klassenaufgabe',break:'Pause'})[v]||v||'–'}
function participantStateLabel(v){return({working:'Arbeitet',done:'Fertig',help:'Hilfe',unsure:'Unsicher'})[v]||v||'Arbeitet'}
function setTeacherControlsEnabled(enabled){['#classroomPhase','#classroomTraffic','#classLockAll','#classWriteAll','#classFollowAll','#classFreeze','#classMessage','#sendClassMessage','#closeClassroom','#toggleContributions','#contributionFilter','#clearContributions'].forEach(id=>{const el=$(id);if(el)el.disabled=!enabled})}
function updateClassroomPanel(){const active=!!classroom?.room_code,code=active?classroom.room_code:'------',urls=classroomUrls();$('#roomCodeValue').textContent=code;$('#roomInfo').textContent=active?'Raum ist aktiv. Steuerung wird live synchronisiert.':'Noch kein Raum gestartet.';$('#classroomLiveDot').classList.toggle('on',active);['#copyRoomCode','#openPresentation','#openStudentView','#copyStudentLink','#showClassroomQr'].forEach(id=>{const el=$(id);if(el)el.disabled=!active});setTeacherControlsEnabled(active);if(active){$('#openPresentation').onclick=()=>window.open(urls.present,'_blank','noopener');$('#openStudentView').onclick=()=>window.open(urls.student,'_blank','noopener');$('#copyRoomCode').onclick=async()=>{await navigator.clipboard.writeText(code);toast('Raumcode kopiert')};$('#copyStudentLink').onclick=async()=>{await navigator.clipboard.writeText(urls.student);toast('Schülerlink kopiert')};$('#showClassroomQr').onclick=()=>showClassroomReady({name:teacherControlState?.class_name||'Klassenraum'})}else{$('#roomConnectedCount').textContent='0';$('#roomRosterCount').textContent='–';$('#roomHelpCount').textContent='0';$('#participantSummary').textContent='0 verbunden';$('#participantList').innerHTML='<div class="participantEmpty">Noch niemand verbunden.</div>';$('#teacherPollState').textContent='nicht verbunden'}}
let classroomSyncHash='',classroomSyncBusy=false;
async function syncClassroom(force=false){if(!classroom?.session_id||!classroom?.teacher_token||classroomSyncBusy)return;const data=serialize(),viewport={scale,tx,ty},signature=JSON.stringify([data,viewport]);if(!force&&signature===classroomSyncHash)return;classroomSyncBusy=true;try{const ok=await rpc('classroom_teacher_sync',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_board_state:data,p_viewport:viewport});if(ok)classroomSyncHash=signature;else throw Error('Classroom-Session ist nicht mehr aktiv')}catch(e){console.warn('Classroom sync',e)}finally{classroomSyncBusy=false}}
function startClassroomSync(){clearInterval(pollTimer);classroomSyncHash='';syncClassroom(true);pollTimer=setInterval(()=>syncClassroom(false),2200)}
async function teacherCommand(command,value={},participant=null,{quiet=false}={}){if(!classroom?.session_id)return false;try{const ok=await rpc('classroom_teacher_command',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_command:command,p_participant:participant,p_value:value});if(!ok)throw Error('Befehl wurde nicht übernommen');if(!quiet)toast('Klassenraum aktualisiert');await pollTeacherControl(true);return true}catch(e){console.error('Teacher command',command,e);toast('Steuerung fehlgeschlagen');return false}}
function ensureContributionLayer(){let cv=$('#classroomContributionInk');if(!cv){cv=document.createElement('canvas');cv.id='classroomContributionInk';cv.width=6000;cv.height=4000;cv.className='classroomContributionInk';world.appendChild(cv)}let textLayer=$('#classroomContributionText');if(!textLayer){textLayer=document.createElement('div');textLayer.id='classroomContributionText';textLayer.className='classroomContributionText';world.appendChild(textLayer)}return{cv,ctx:cv.getContext('2d'),textLayer}}
function contributionActiveEvents(events){const byStudent=new Map();for(const e of events){const id=e.participant_id,p=e.payload||{};if(!byStudent.has(id))byStudent.set(id,{legacy:[],snapshot:null,name:e.name});const bucket=byStudent.get(id);bucket.name=e.name||bucket.name;if(p.type==='snapshot'&&p.workspace){bucket.snapshot=e;bucket.legacy=[];continue}if(bucket.snapshot)continue;if(p.type==='clear')bucket.legacy=[];else if(p.type==='undo')bucket.legacy.pop();else if(p.type==='stroke'||p.type==='text')bucket.legacy.push(e)}const out=[];for(const [participant_id,b] of byStudent){if(b.snapshot){const ws=b.snapshot.payload.workspace||{};for(const st of ws.strokes||[])out.push({id:b.snapshot.id,participant_id,name:b.name,payload:{type:'stroke',stroke:st}});for(const item of ws.items||[])out.push({id:b.snapshot.id,participant_id,name:b.name,payload:{type:'workspace_item',item}})}else out.push(...b.legacy)}return out}
function renderTeacherContributions(){const {cv,ctx,textLayer}=ensureContributionLayer();cv.style.display=teacherContributionsVisible?'block':'none';textLayer.style.display=teacherContributionsVisible?'block':'none';ctx.clearRect(0,0,cv.width,cv.height);textLayer.innerHTML='';if(!teacherContributionsVisible)return;const active=contributionActiveEvents(teacherContributionEvents).filter(e=>teacherContributionFilter==='all'||e.participant_id===teacherContributionFilter);ctx.lineCap='round';ctx.lineJoin='round';for(const e of active){const p=e.payload||{};if(p.type==='stroke'&&p.stroke){const st=p.stroke;ctx.beginPath();ctx.strokeStyle=st.color||'#6d4d73';ctx.lineWidth=st.width||4;ctx.globalAlpha=st.alpha??1;(st.points||[]).forEach((pt,i)=>i?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y));ctx.stroke();ctx.globalAlpha=1}else if(p.type==='text'){const el=document.createElement('div');el.className='studentContributionText';el.style.left=(+p.x||0)+'px';el.style.top=(+p.y||0)+'px';el.style.color=p.color||'#5b4164';el.style.fontSize=Math.min(96,Math.max(14,+p.size||28))+'px';el.style.fontWeight=p.bold?'900':'750';el.textContent=p.text||'';el.title=e.name||'';textLayer.appendChild(el)}else if(p.type==='workspace_item'&&p.item){const i=p.item,el=document.createElement('div');el.className='studentContributionItem '+(i.type||'');el.style.left=(+i.x||0)+'px';el.style.top=(+i.y||0)+'px';el.style.width=(+i.w||320)+'px';el.style.height=(+i.h||120)+'px';el.style.zIndex=10+(+i.z||0);if(i.type==='image'&&i.src){const im=document.createElement('img');im.src=i.src;im.alt=i.name||'Schülerbild';el.appendChild(im)}else{el.textContent=i.text||'';el.style.color=i.color||'#5b4164';el.style.background=i.type==='sticky'?(i.bg||'#fff0a9'):(i.bg||'rgba(255,255,255,.88)');el.style.fontSize=Math.min(96,Math.max(14,+i.size||28))+'px';el.style.fontWeight=i.bold?'900':'500';el.style.fontFamily=i.font||'Inter,Arial,sans-serif';el.style.textAlign=i.align||'left';el.style.whiteSpace='pre-wrap'}el.title=e.name||'';textLayer.appendChild(el)}}const count=active.length;$('#contributionSummary').textContent=count+' '+(count===1?'Beitrag':'Beiträge')}
async function pollTeacherContributions(reset=false){if(!classroom?.session_id||teacherContributionBusy)return;teacherContributionBusy=true;try{if(reset){teacherContributionAfterId=0;teacherContributionEvents=[]}const r=await rpc('classroom_teacher_contributions',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_after_id:teacherContributionAfterId});if(!r?.ok)throw Error('Contributions ungültig');const incoming=Array.isArray(r.events)?r.events:[];if(incoming.length)teacherContributionEvents.push(...incoming);teacherContributionAfterId=Number(r.last_id)||teacherContributionAfterId;renderTeacherContributions()}catch(e){console.warn('Teacher contributions',e);$('#contributionSummary').textContent='SQL-Patch erforderlich'}finally{teacherContributionBusy=false}}
function updateContributionFilter(){const sel=$('#contributionFilter'),ps=teacherControlState?.participants||[],current=teacherContributionFilter;sel.innerHTML='<option value="all">Alle Schüler</option>'+ps.map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('');if([...sel.options].some(o=>o.value===current))sel.value=current;else{teacherContributionFilter='all';sel.value='all'}}
function renderParticipantList(){const list=$('#participantList'),all=teacherControlState?.participants||[],rows=all.filter(p=>participantFilter==='all'||p.state===participantFilter);if(!rows.length){list.innerHTML='<div class="participantEmpty">'+(all.length?'Keine Schüler in diesem Filter.':'Noch niemand verbunden.')+'</div>';return}list.innerHTML=rows.map(p=>'<article class="participantCard '+(p.online?'online':'offline')+' '+(p.state==='help'?'needsHelp':'')+'"><div class="participantMain"><span class="participantDot"></span><div><b>'+esc(p.name)+'</b><small>'+participantStateLabel(p.state)+' · '+(p.online?'online':'offline')+'</small></div><span class="participantState state-'+esc(p.state)+'">'+participantStateLabel(p.state)+'</span></div><div class="participantControls"><button data-p-action="lock" data-id="'+p.id+'" data-on="'+(p.locked?'1':'0')+'">'+(p.locked?'🔒 Gesperrt':'🔓 Frei')+'</button><button data-p-action="write" data-id="'+p.id+'" data-on="'+(p.can_write?'1':'0')+'">'+(p.can_write?'✏️ Schreiben':'✏️ Lesen')+'</button><button data-p-action="follow" data-id="'+p.id+'" data-on="'+(p.follow_teacher?'1':'0')+'">'+(p.follow_teacher?'👀 Folgt':'👀 Frei')+'</button><button data-p-action="message" data-id="'+p.id+'" data-name="'+esc(p.name)+'">💬</button></div></article>').join('');$('[data-p-action]').forEach(btn=>btn.onclick=async()=>{const id=btn.dataset.id,act=btn.dataset.pAction,on=btn.dataset.on==='1';if(act==='lock')await teacherCommand(on?'unlock_one':'lock_one',{},id);else if(act==='write')await teacherCommand('write_one',{enabled:!on},id);else if(act==='follow')await teacherCommand('follow_one',{enabled:!on},id);else if(act==='view'){teacherContributionFilter=id;$('#contributionFilter').value=id;teacherContributionsVisible=true;$('#toggleContributions').dataset.on='1';$('#toggleContributions').textContent='👁 Beiträge sichtbar';renderTeacherContributions()}else if(act==='message'){const body=prompt('Nachricht an '+btn.dataset.name+':');if(body?.trim())await teacherCommand('message',{body:body.trim()},id)}})}
function renderTeacherControl(){const s=teacherControlState;if(!s?.ok)return;const ps=Array.isArray(s.participants)?s.participants:[],online=ps.filter(p=>p.online).length,help=ps.filter(p=>p.state==='help').length,roster=Number.isFinite(+s.roster_count)?+s.roster_count:null;$('#roomConnectedCount').textContent=online;$('#roomRosterCount').textContent=roster??'–';$('#roomHelpCount').textContent=help;$('#participantSummary').textContent=online+(roster!==null?' / '+roster:'')+' verbunden';$('#teacherPollState').textContent='live · '+phaseLabel(s.phase);$('#classroomPhase').value=s.phase||'free';$('#classroomTraffic').value=s.traffic||'green';const any=ps.length>0,allLocked=typeof s.class_locked==='boolean'?s.class_locked:(any&&ps.every(p=>p.locked)),allWrite=typeof s.class_can_write==='boolean'?s.class_can_write:(any&&ps.every(p=>p.can_write)),allFollow=typeof s.class_follow_teacher==='boolean'?s.class_follow_teacher:(any&&ps.every(p=>p.follow_teacher));$('#classLockAll').dataset.on=allLocked?'1':'0';$('#classLockAll').textContent=allLocked?'🔒 Alle gesperrt':'🔓 Alle entsperrt';$('#classWriteAll').dataset.on=allWrite?'1':'0';$('#classWriteAll').textContent=allWrite?'✏️ Schreiben an':'✏️ Schreiben aus';$('#classFollowAll').dataset.on=allFollow?'1':'0';$('#classFollowAll').textContent=allFollow?'👀 Lehreransicht':'👀 Freie Ansicht';$('#classFreeze').dataset.on=s.frozen?'1':'0';$('#classFreeze').textContent=s.frozen?'⏸ Beamer eingefroren':'▶ Beamer live';renderParticipantList();updateContributionFilter()}
async function pollTeacherControl(force=false){if(!classroom?.session_id||teacherControlBusy)return;teacherControlBusy=true;try{const state=await rpc('classroom_teacher_state',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token});if(!state?.ok)throw Error('Session ungültig');teacherControlState=state;renderTeacherControl();$('#classroomLiveDot').classList.add('on');pollTeacherContributions(false)}catch(e){console.warn('Teacher control polling',e);$('#teacherPollState').textContent='Verbindung unterbrochen';$('#classroomLiveDot').classList.remove('on');if(force)toast('Teacher Control nicht erreichbar')}finally{teacherControlBusy=false}}
function startTeacherControl(){clearInterval(teacherControlTimer);teacherContributionAfterId=0;teacherContributionEvents=[];pollTeacherControl(true);pollTeacherContributions(true);teacherControlTimer=setInterval(()=>pollTeacherControl(false),1800)}
function stopTeacherControl(){clearInterval(teacherControlTimer);teacherControlTimer=null;teacherControlState=null}
function renderClassroomSetup(){const lists=window.KathleenClassLists?.load?.()||[],sel=$('#classroomClassSelect');sel.innerHTML=lists.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' · '+c.students.length+' Schüler</option>').join('');const last=localStorage.getItem('kathleenLastClassroomClass');if(last&&lists.some(c=>c.id===last))sel.value=last;const renderPreview=()=>{const c=lists.find(x=>x.id===sel.value);$('#classroomRosterPreview').innerHTML=c?'<b>'+esc(c.name)+'</b><span>'+c.students.length+' Schüler</span><div>'+c.students.slice(0,10).map(n=>'<i>'+esc(n)+'</i>').join('')+(c.students.length>10?'<i>+'+(c.students.length-10)+'</i>':'')+'</div>':'<span>Keine Klasse gewählt.</span>'};sel.onchange=renderPreview;renderPreview();return lists}
function showClassroomReady(classInfo){const urls=classroomUrls();$('#classroomSetupStep').classList.add('hidden');$('#classroomReadyStep').classList.remove('hidden');$('#classroomReadyTitle').textContent=classInfo?.name||teacherControlState?.class_name||'Klassenraum';$('#classroomReadyCode').textContent=classroom.room_code;const q=$('#classroomQr');q.innerHTML='';if(window.QRCode)new QRCode(q,{text:urls.student,width:220,height:220,correctLevel:QRCode.CorrectLevel.M});$('#classroomReadyBeamer').onclick=()=>window.open(urls.present,'_blank','noopener');$('#classroomReadyStudent').onclick=()=>window.open(urls.student,'_blank','noopener');$('#classroomReadyCopy').onclick=async()=>{await navigator.clipboard.writeText(urls.student);toast('Schülerlink kopiert')};$('#classroomStartModal').classList.remove('hidden')}
async function openClassroomSetup(){const ok=await window.KathleenClassLists?.requireUnlock?.();if(ok===false)return;const lists=renderClassroomSetup();if(!lists.length){toast('Bitte zuerst eine Klassenliste anlegen');return}$('#classroomReadyStep').classList.add('hidden');$('#classroomSetupStep').classList.remove('hidden');$('#classroomStartModal').classList.remove('hidden')}
$('#roomBtn').onclick=openClassroomSetup;$('#classroomStartClose').onclick=()=>$('#classroomStartModal').classList.add('hidden');$('#classroomStartModal').onclick=e=>{if(e.target.id==='classroomStartModal')$('#classroomStartModal').classList.add('hidden')};
$('#classroomStartConfirm').onclick=async()=>{const lists=window.KathleenClassLists?.load?.()||[],selected=lists.find(x=>x.id===$('#classroomClassSelect').value);if(!selected)return;try{const pass=sessionStorage.getItem('kathleenAdminPass')||prompt('Kisten-Adminpasswort');if(!pass)return;const verified=!!(await rpc('classroom_authenticate',{p_passphrase:pass}));if(!verified){sessionStorage.removeItem('kathleenAdminPass');toast('Admin-Passwort falsch');return}classroom=await rpc('classroom_create',{p_passphrase:pass,p_title:board.name||'Unterricht',p_class_name:selected.name});const rosterOk=await rpc('classroom_set_roster',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_class_name:selected.name,p_names:selected.students});if(!rosterOk)throw Error('Klassenliste konnte nicht übertragen werden');const rosterCheck=await rpc('classroom_roster',{p_room_code:classroom.room_code});if(!rosterCheck?.ok||!Array.isArray(rosterCheck.students)||rosterCheck.students.length!==selected.students.length)throw Error('Klassenliste ist serverseitig nicht bereit');sessionStorage.setItem('kathleenAdminPass',pass);sessionStorage.setItem('kathleenClassroom',JSON.stringify(classroom));localStorage.setItem('kathleenLastClassroomClass',selected.id);updateClassroomPanel();$('#studentsPanel').classList.remove('hidden');$('#studentsPanel').classList.add('teacherPersistent');applyTeacherWindowLayout();startClassroomSync();startTeacherControl();showClassroomReady(selected);toast('Raum '+classroom.room_code+' gestartet')}catch(e){console.error(e);const m=String(e.message||'');if(/classroom_|schema cache|function .* does not exist|PGRST202/i.test(m))toast('Classroom-SQL fehlt oder ist veraltet');else toast('Raumstart: '+m.slice(0,90))}};
$('#classroomPhase').onchange=e=>teacherCommand('phase',{phase:e.target.value});
$('#classroomTraffic').onchange=e=>teacherCommand('traffic',{traffic:e.target.value});
$('#classLockAll').onclick=()=>teacherCommand($('#classLockAll').dataset.on==='1'?'unlock_all':'lock_all');
$('#classWriteAll').onclick=()=>teacherCommand('class_write',{enabled:$('#classWriteAll').dataset.on!=='1'});
$('#classFollowAll').onclick=()=>teacherCommand('follow_all',{enabled:$('#classFollowAll').dataset.on!=='1'});
$('#classFreeze').onclick=()=>teacherCommand('freeze',{enabled:$('#classFreeze').dataset.on!=='1'});
$('[data-participant-filter]').forEach(b=>b.onclick=()=>{$('[data-participant-filter]').forEach(x=>x.classList.toggle('active',x===b));participantFilter=b.dataset.participantFilter;renderParticipantList()});
$('#sendClassMessage').onclick=async()=>{const input=$('#classMessage'),body=input.value.trim();if(!body)return;if(await teacherCommand('message',{body},null))input.value=''};
$('#classMessage').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#sendClassMessage').click()}});
$('#toggleContributions').onclick=()=>{teacherContributionsVisible=!teacherContributionsVisible;$('#toggleContributions').dataset.on=teacherContributionsVisible?'1':'0';$('#toggleContributions').textContent=teacherContributionsVisible?'👁 Beiträge sichtbar':'🙈 Beiträge verborgen';renderTeacherContributions()};
$('#contributionFilter').onchange=e=>{teacherContributionFilter=e.target.value;renderTeacherContributions()};
$('#clearContributions').onclick=async()=>{if(!confirm(teacherContributionFilter==='all'?'Alle Schülerbeiträge wirklich löschen?':'Beiträge dieses Schülers wirklich löschen?'))return;const participant=teacherContributionFilter==='all'?null:teacherContributionFilter;if(await teacherCommand('clear_contributions',{},participant,{quiet:true})){await pollTeacherContributions(true);toast('Beiträge gelöscht')}};
$('#closeClassroom').onclick=async()=>{if(!classroom||!confirm('Klassenraum wirklich beenden? Schüler werden getrennt.'))return;if(await teacherCommand('close',{},null,{quiet:true})){clearInterval(pollTimer);stopTeacherControl();sessionStorage.removeItem('kathleenClassroom');classroom=null;updateClassroomPanel();toast('Klassenraum beendet')}};
async function restoreClassroomSession(){try{classroom=JSON.parse(sessionStorage.getItem('kathleenClassroom')||'null');if(!classroom)return;const state=await rpc('classroom_teacher_state',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token});if(!state?.ok||state.session_state!=='open'){classroom=null;sessionStorage.removeItem('kathleenClassroom');updateClassroomPanel();return}teacherControlState=state;updateClassroomPanel();renderTeacherControl();applyTeacherWindowLayout();startClassroomSync();startTeacherControl()}catch(e){console.warn('Stored Classroom session invalid',e);classroom=null;sessionStorage.removeItem('kathleenClassroom');updateClassroomPanel()}}
setupTeacherWindow();
restoreClassroomSession();
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&selectedItems.length&&!e.target.isContentEditable){e.preventDefault();duplicateSelected();return}if((e.key==='Delete'||e.key==='Backspace')&&selectedItems.length&&!e.target.isContentEditable&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();deleteSelected()}});window.addEventListener('keydown',e=>{if(e.key==='Escape'){select(null);hideBoardLibrary()}});window.addEventListener('resize',placeSelectionBar);(async()=>{await load();select(null);setTool('select');transform()})();
